//! Rust-owned SQL for advancing a Flow event after a workflow command.
//!
//! The TypeScript adapter binds and executes these on the caller transaction so
//! command, guards, receipt and after-effects stay in one serializable unit.
//! `flow-advance-sql.json` mirrors this table and the test below keeps both in
//! lockstep, exactly like the command-assertion contract.
pub const KINDS: &[&str] = &[
    "expense",
    "leave",
    "staff_task",
    "request",
    "stock_count",
    "transfer",
    "order",
    "invoice",
    "journal",
    "payroll",
    "record",
];

/// Exact per-kind UPDATE statement. Binds: kind, command key, company id, record id.
pub fn flow_advance_sql(kind: &str) -> Option<&'static str> {
    Some(match kind {
        "expense" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.workflow_stage='department_approval' AND EXISTS(SELECT 1 FROM approval_steps s JOIN approval_instances i ON i.id=s.instance_id WHERE i.record_type='expense' AND i.record_id=d.id AND i.company_id=d.company_id AND s.ordinal=(SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1) AND jsonb_exists(s.route_snapshot_json::jsonb,'departmentPolicyVersion')) THEN 'department_approval_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text WHEN d.workflow_version=2 THEN d.workflow_stage ELSE CASE d.status WHEN 'in_review' THEN 'department_approval' WHEN 'approved' THEN 'gl_posting' WHEN 'posted' THEN 'payment' WHEN 'rejected' THEN 'draft' ELSE d.status END END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.workflow_stage='department_approval' AND EXISTS(SELECT 1 FROM approval_steps s JOIN approval_instances i ON i.id=s.instance_id WHERE i.record_type='expense' AND i.record_id=d.id AND i.company_id=d.company_id AND s.ordinal=(SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1) AND jsonb_exists(s.route_snapshot_json::jsonb,'departmentPolicyVersion')) THEN 'department_approval_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text WHEN d.workflow_version=2 THEN d.workflow_stage ELSE CASE d.status WHEN 'in_review' THEN 'department_approval' WHEN 'approved' THEN 'gl_posting' WHEN 'posted' THEN 'payment' WHEN 'rejected' THEN 'draft' ELSE d.status END END) ->> 'primaryUserId') FROM finance_expenses d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "invoice" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.status='partially_paid' THEN 'posted' ELSE d.status END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.status='partially_paid' THEN 'posted' ELSE d.status END) ->> 'primaryUserId') FROM finance_invoices d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "journal" => r#"UPDATE flow_events e SET next_step_key=(d.status),next_user_id=(r.steps_json::jsonb -> (d.status) ->> 'primaryUserId') FROM finance_journals d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "leave" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.state='pending_approval' THEN 'approval_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text ELSE d.state END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.state='pending_approval' THEN 'approval_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text ELSE d.state END) ->> 'primaryUserId') FROM leave_requests d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "order" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.state='partially_fulfilled' THEN 'confirmed' WHEN d.state='fulfilled' AND EXISTS(SELECT 1 FROM (SELECT "id","order_id","number","fulfillment_date","created_by","created_at","journal_id","invoice_id","version","evidence_note" FROM commerce_fulfillments) f JOIN (SELECT "id","company_id","chart_id","period_id","journal_number","entry_date","currency","fx_rate_micros","source_type","source_id","memo","status","is_opening","version","created_by","posted_by","posted_at","reversed_by","reversed_at","created_at","updated_at" FROM finance_journals) j ON j.id=f.journal_id WHERE f.order_id=d.id AND j.status IN ('draft','in_review')) THEN 'stock_gl' WHEN d.state='fulfilled' AND EXISTS(SELECT 1 FROM (SELECT "id","order_id","number","fulfillment_date","created_by","created_at","journal_id","invoice_id","version","evidence_note" FROM commerce_fulfillments) f WHERE f.order_id=d.id AND f.invoice_id IS NULL) THEN 'invoicing' ELSE d.state END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.state='partially_fulfilled' THEN 'confirmed' WHEN d.state='fulfilled' AND EXISTS(SELECT 1 FROM (SELECT "id","order_id","number","fulfillment_date","created_by","created_at","journal_id","invoice_id","version","evidence_note" FROM commerce_fulfillments) f JOIN (SELECT "id","company_id","chart_id","period_id","journal_number","entry_date","currency","fx_rate_micros","source_type","source_id","memo","status","is_opening","version","created_by","posted_by","posted_at","reversed_by","reversed_at","created_at","updated_at" FROM finance_journals) j ON j.id=f.journal_id WHERE f.order_id=d.id AND j.status IN ('draft','in_review')) THEN 'stock_gl' WHEN d.state='fulfilled' AND EXISTS(SELECT 1 FROM (SELECT "id","order_id","number","fulfillment_date","created_by","created_at","journal_id","invoice_id","version","evidence_note" FROM commerce_fulfillments) f WHERE f.order_id=d.id AND f.invoice_id IS NULL) THEN 'invoicing' ELSE d.state END) ->> 'primaryUserId') FROM commerce_orders d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "payroll" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.status='posted' THEN COALESCE((SELECT CASE status WHEN 'draft' THEN 'payment_draft' WHEN 'approved' THEN 'payment_approved' WHEN 'exported' THEN 'payment_exported' WHEN 'partially_settled' THEN 'payment_partially_settled' WHEN 'settled' THEN 'payment_settled' ELSE 'posted' END FROM (SELECT "id","company_id","source_type","source_id","currency","status","format_code","file_key","file_checksum","total_minor","version","created_by","approved_by","exported_at","created_at","updated_at","bank_account_id","retry_requested_by" FROM hr_payment_batches) hr_payment_batches WHERE company_id=d.company_id AND source_type='payroll' AND source_id=d.id AND status<>'cancelled' ORDER BY created_at DESC,id DESC LIMIT 1),'posted') ELSE d.status END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.status='posted' THEN COALESCE((SELECT CASE status WHEN 'draft' THEN 'payment_draft' WHEN 'approved' THEN 'payment_approved' WHEN 'exported' THEN 'payment_exported' WHEN 'partially_settled' THEN 'payment_partially_settled' WHEN 'settled' THEN 'payment_settled' ELSE 'posted' END FROM (SELECT "id","company_id","source_type","source_id","currency","status","format_code","file_key","file_checksum","total_minor","version","created_by","approved_by","exported_at","created_at","updated_at","bank_account_id","retry_requested_by" FROM hr_payment_batches) hr_payment_batches WHERE company_id=d.company_id AND source_type='payroll' AND source_id=d.id AND status<>'cancelled' ORDER BY created_at DESC,id DESC LIMIT 1),'posted') ELSE d.status END) ->> 'primaryUserId') FROM hr_payroll_runs d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "record" => r#"UPDATE flow_events e SET next_step_key=(d.status),next_user_id=(r.steps_json::jsonb -> (d.status) ->> 'primaryUserId') FROM workspace_records d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "request" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.state IN ('resolved','fulfilled') THEN 'confirm' WHEN d.state='returned' THEN 'draft' WHEN d.state='awaiting_approval' AND d.approval_json::jsonb #>> '{route,steps,0,snapshot,departmentPolicyVersion}' IS NOT NULL THEN 'purchase_' || COALESCE((d.approval_json::jsonb ->> 'currentStep')::int,0)::text WHEN d.state='awaiting_approval' AND d.approval_json::jsonb #>> '{route,steps,0,snapshot,spendingPolicy}' IS NOT NULL THEN 'purchase_' || (d.approval_json::jsonb #> '{route,steps}' -> COALESCE((d.approval_json::jsonb ->> 'currentStep')::int,0) ->> 'stage') ELSE d.state END),next_user_id=(CASE WHEN d.state='in_progress' THEN d.assignee_user_id ELSE r.steps_json::jsonb -> (CASE WHEN d.state IN ('resolved','fulfilled') THEN 'confirm' WHEN d.state='returned' THEN 'draft' WHEN d.state='awaiting_approval' AND d.approval_json::jsonb #>> '{route,steps,0,snapshot,departmentPolicyVersion}' IS NOT NULL THEN 'purchase_' || COALESCE((d.approval_json::jsonb ->> 'currentStep')::int,0)::text WHEN d.state='awaiting_approval' AND d.approval_json::jsonb #>> '{route,steps,0,snapshot,spendingPolicy}' IS NOT NULL THEN 'purchase_' || (d.approval_json::jsonb #> '{route,steps}' -> COALESCE((d.approval_json::jsonb ->> 'currentStep')::int,0) ->> 'stage') ELSE d.state END) ->> 'primaryUserId' END) FROM employee_requests d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "staff_task" => r#"UPDATE flow_events e SET next_step_key=(CASE WHEN d.state IN ('ready','in_progress','rework') THEN 'work' WHEN d.state='start_approval' THEN 'start_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text WHEN d.state='completion_approval' THEN 'completion_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text ELSE d.state END),next_user_id=(r.steps_json::jsonb -> (CASE WHEN d.state IN ('ready','in_progress','rework') THEN 'work' WHEN d.state='start_approval' THEN 'start_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text WHEN d.state='completion_approval' THEN 'completion_' || ((SELECT current_step FROM approval_instances WHERE company_id=d.company_id AND record_id=d.id ORDER BY insertion_order DESC LIMIT 1))::text ELSE d.state END) ->> 'primaryUserId') FROM staff_tasks d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "stock_count" => r#"UPDATE flow_events e SET next_step_key=(d.status),next_user_id=(r.steps_json::jsonb -> (d.status) ->> 'primaryUserId') FROM inventory_counts d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        "transfer" => r#"UPDATE flow_events e SET next_step_key=(d.status),next_user_id=(r.steps_json::jsonb -> (d.status) ->> 'primaryUserId') FROM inventory_transfers d JOIN flow_routes r ON r.company_id=d.company_id AND r.kind=? AND r.record_id=d.id WHERE e.command_id=? AND d.company_id=? AND d.id=?"#,
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn contract_matches_owned_sql() {
        let contract: serde_json::Value =
            serde_json::from_str(include_str!("../flow-advance-sql.json")).expect("contract json");
        let object = contract.as_object().expect("contract object");
        assert_eq!(object.len(), KINDS.len());
        for kind in KINDS {
            let expected = object.get(*kind).and_then(|value| value.as_str()).expect(kind);
            assert_eq!(flow_advance_sql(kind), Some(expected), "{kind}");
        }
        assert_eq!(flow_advance_sql("unknown"), None);
    }
}
